function Modal({title,subtitle,children,onClose,wide=false}:{title:string;subtitle?:string;children:ReactNode;onClose:()=>void;wide?:boolean}) {const dialogRef=useDialogFocus(onClose);return <div className="modal-backdrop" onClick={onClose}><section ref={dialogRef} role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide?'modal-wide':''}`} onClick={e=>e.stopPropagation()}><div className="modal-heading"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-btn" aria-label="Fechar janela" onClick={onClose}><X size={20}/></button></div>{children}</section></div>;}
function useDialogFocus(onClose:()=>void){const ref=useRef<HTMLElement|null>(null),close=useRef(onClose);close.current=onClose;useEffect(()=>{const previous=document.activeElement as HTMLElement|null,overflow=document.body.style.overflow;document.body.style.overflow='hidden';const frame=requestAnimationFrame(()=>ref.current?.querySelector<HTMLElement>('input:not([type=file]):not(:disabled),textarea:not(:disabled),select:not(:disabled),button:not(:disabled)')?.focus());const key=(event:KeyboardEvent)=>{const dialogs=document.querySelectorAll('[role="dialog"]');if(ref.current!==dialogs[dialogs.length-1])return;if(event.key==='Escape'){event.preventDefault();close.current();}if(event.key==='Tab'){const items=Array.from(ref.current!.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')).filter(el=>el.getClientRects().length>0&&el.tabIndex>=0);const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);return()=>{cancelAnimationFrame(frame);document.removeEventListener('keydown',key);document.body.style.overflow=overflow;if(previous?.isConnected)previous.focus();};},[]);return ref;}
function ChangePasswordModal({onClose,onDone}:{onClose:()=>void;onDone:()=>Promise<void>}){const [old,setOld]=useState(''),[password,setPassword]=useState(''),[confirm,setConfirm]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');return <Modal title="Alterar minha senha" subtitle="Após salvar, você entrará novamente com a nova senha." onClose={onClose}><form onSubmit={async e=>{e.preventDefault();setError('');if(!validatePassword(password))return setError('Use de 8 a 12 caracteres com letras e números, sem símbolos ou espaços.');if(password!==confirm)return setError('A confirmação não confere.');if(old===password)return setError('Escolha uma senha diferente da atual.');setBusy(true);try{await gateway('auth/password',{old_password:old,password});await onDone();}catch(e){setError(message(e));}finally{setBusy(false);}}}><label>Senha atual<input type="password" autoComplete="current-password" value={old} onChange={e=>setOld(e.target.value)} required/></label><label>Nova senha<input type="password" autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)} minLength={8} maxLength={12} required/></label><small>Entre 8 e 12 caracteres, com letras e números.</small><label>Confirmar nova senha<input type="password" autoComplete="new-password" value={confirm} onChange={e=>setConfirm(e.target.value)} required/></label>{error&&<p className="form-error">{error}</p>}<div className="modal-actions"><Button kind="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" icon={Check} disabled={busy}>Salvar nova senha</Button></div></form></Modal>;}
