function LoginScreen({onLogin,onDemo}:{onLogin:(p:Profile)=>void;onDemo:()=>void}) {
 const [username,setUsername]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[recover,setRecover]=useState(false),[sent,setSent]=useState(false);
 async function submit(e:FormEvent) {e.preventDefault();setBusy(true);setError('');try{if(recover){await gateway('auth/recover',{username},true);setSent(true);}else onLogin(await login(username.trim().toLowerCase(),password));}catch(e){setError(message(e));}finally{setBusy(false);}}
 return <div className="login-page"><aside className="login-story"><Brand/><div className="login-copy"><span className="eyebrow"><span/> UM ESPAÇO PARA SUA EQUIPE</span><h1>Menos pendências.<br/>Mais <em>fluxo.</em></h1><p>Organize o trabalho, conecte a equipe e acompanhe cada entrega. Tudo em um só lugar.</p><div className="login-art" aria-hidden="true"><div className="art-heading"><span>Seu trabalho, em movimento</span><MoreHorizontal size={18}/></div><div className="art-cols">{['Pendente','Em andamento','Resolvido'].map((s,i)=><div key={s}><div className="art-col-label"><i className={`art-dot-${i}`}/>{s}</div>{Array.from({length:i===1?2:1},(_,j)=><div className={`art-card art-card-${i}`} key={j}><div className="art-line"/><div className="art-line short"/><div className="art-card-bottom"><span className="art-pill"/><span className="art-avatar">{i===2?<Check size={11}/>:''}</span></div></div>)}</div>)}</div><div className="art-note"><CheckCircle2 size={17}/> Cada entrega conta.</div></div></div><footer><span>Feito para equipes de TI.</span><span>Clareza em cada etapa <ArrowUpRight size={14}/></span></footer></aside><main className="login-main"><div className="login-top"><span>Automações TI</span><ShieldCheck size={16}/></div><div className="login-form"><span className="login-icon"><LockKeyhole size={23}/></span><h2>{recover?'Recuperar acesso':'Bom ter você por aqui.'}</h2><p>{recover?'Informe seu login para receber as instruções por e-mail.':'Entre na sua conta e dê continuidade ao que importa.'}</p>{!configured&&<div className="notice"><span className="notice-dot"/><div><strong>Ambiente em preparação</strong><p>A conexão com o Supabase e o serviço de e-mail aguardam configuração. Explore a demonstração abaixo.</p></div></div>}{configured&&demoAvailable&&<div className="notice"><Mail size={18}/><div><strong>Acesso em ativação</strong><p>O banco está conectado. A liberação das contas e os e-mails de acesso estão sendo configurados. Enquanto isso, explore a demonstração.</p></div></div>}{sent?<div className="success-message"><CheckCircle2/> Se o login estiver cadastrado, você receberá instruções no e-mail associado.</div>:<form onSubmit={submit}><label>Usuário<input autoComplete="username" placeholder="nome.sobrenome" value={username} onChange={e=>setUsername(e.target.value)} required/></label>{!recover&&<label>Senha<input type="password" autoComplete="current-password" placeholder="Sua senha de acesso" value={password} onChange={e=>setPassword(e.target.value)} required/></label>}{error&&<p className="form-error" role="alert">{error}</p>}<Button type="submit" disabled={busy||!configured} icon={busy?LoaderCircle:ArrowRight} className="login-submit">{busy?'Aguarde…':recover?'Enviar instruções':'Entrar na minha conta'}</Button></form>}<button className="text-btn login-recover" onClick={()=>{setRecover(!recover);setSent(false);setError('');}}>{recover?'Voltar para o login':'Esqueceu sua senha?'}</button>{demoAvailable&&<><div className="login-divider"><span>CONHEÇA O TI FLOW</span></div><Button kind="secondary" icon={LayoutGrid} onClick={onDemo}>Explorar demonstração <ArrowUpRight size={15}/></Button><small className="demo-help">Dados fictícios, salvos apenas neste navegador.</small></>}<div className="login-security"><ShieldCheck size={14}/> Acesso exclusivo para usuários autorizados.</div></div><footer className="login-footer">TI Flow <span>Organização que faz a diferença.</span></footer></main></div>;
}
function PasswordScreen({onDone}:{onDone:()=>void}) {const [old,setOld]=useState(''),[value,setValue]=useState(''),[confirm,setConfirm]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();setError('');if(!validatePassword(value))return setError('Use de 8 a 12 caracteres, contendo letras e números, sem espaços ou símbolos.');if(value!==confirm)return setError('A confirmação da senha não confere.');if(old===value)return setError('Escolha uma senha diferente da temporária.');setBusy(true);try{await gateway('auth/password',{old_password:old,password:value});await supabase?.auth.signOut({scope:'local'});onDone();}catch(e){setError(message(e));}finally{setBusy(false);}}return <div className="password-page"><Brand/><div className="password-card"><span className="login-icon"><LockKeyhole/></span><h1>Seu acesso começa com segurança.</h1><p>Antes de continuar, substitua a senha temporária por uma senha só sua.</p><form onSubmit={submit}><label>Senha temporária<input type="password" value={old} onChange={e=>setOld(e.target.value)} autoComplete="current-password" required/></label><label>Nova senha<input type="password" value={value} onChange={e=>setValue(e.target.value)} minLength={8} maxLength={12} autoComplete="new-password" required/></label><small>De 8 a 12 caracteres, com letras e números. Sem símbolos ou espaços.</small><label>Confirme a nova senha<input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} autoComplete="new-password" required/></label>{error&&<p className="form-error">{error}</p>}<Button type="submit" disabled={busy} icon={Check}>Salvar nova senha</Button></form><button className="text-btn" onClick={async()=>{await supabase?.auth.signOut({scope:'local'});onDone();}}>Sair e continuar depois</button></div></div>;}
function RecoveryScreen({token,onDone}:{token:string;onDone:()=>void}) {const [password,setPassword]=useState(''),[confirm,setConfirm]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[done,setDone]=useState(false);async function submit(e:FormEvent){e.preventDefault();setError('');if(!validatePassword(password))return setError('Use de 8 a 12 caracteres com letras e números, sem símbolos ou espaços.');if(password!==confirm)return setError('A confirmação não confere.');setBusy(true);try{await gateway('auth/reset',{token,password},true);await supabase?.auth.signOut({scope:'local'});setDone(true);}catch(e){setError(message(e));}finally{setBusy(false);}}return <div className="password-page"><Brand/><div className="password-card"><span className="login-icon"><LockKeyhole/></span><h1>{done?'Seu acesso foi recuperado.':'Escolha sua nova senha.'}</h1><p>{done?'Entre novamente com seu login e a nova senha.':'Use de 8 a 12 caracteres, com letras e números, sem símbolos ou espaços.'}</p>{done?<Button onClick={onDone} icon={ArrowRight}>Voltar ao login</Button>:<form onSubmit={submit}><label>Nova senha<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength={8} maxLength={12} autoComplete="new-password" required/></label><label>Confirme a nova senha<input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} autoComplete="new-password" required/></label>{error&&<p className="form-error">{error}</p>}<Button type="submit" disabled={busy} icon={Check}>Salvar nova senha</Button></form>}</div></div>;}
function message(e:unknown) {return e instanceof Error?e.message:typeof e==='object'&&e!==null&&'message'in e?String(e.message):'Não foi possível concluir. Tente novamente.';}

export default function App() {
 const [recovery,setRecovery]=useState(()=>new URLSearchParams(window.location.search).get('recovery'));
 const [newStatus,setNewStatus]=useState<Status>('pending');
 const [archiveStart,setArchiveStart]=useState(''),[archiveEnd,setArchiveEnd]=useState('');
 const [changingPassword,setChangingPassword]=useState(false);
 const [user,setUser]=useState<Profile|null>(null),[demo,setDemo]=useState(false),[checking,setChecking]=useState(true),[data,setData]=useState<DataSet>({cards:[],profiles:[],events:[]}),[view,setView]=useState<View>('board'),[loading,setLoading]=useState(false),[toast,setToast]=useState<{text:string;error:boolean}|null>(null),[drawer,setDrawer]=useState<Card|'new'|null>(null),[query,setQuery]=useState(''),[assignee,setAssignee]=useState('all'),[priority,setPriority]=useState('all'),[sort,setSort]=useState('manual'),[mobile,setMobile]=useState(false),[showFilters,setShowFilters]=useState(false),[theme,setTheme]=useState(()=>localStorage.getItem('ti-flow-theme')??'light'),[confirmClose,setConfirmClose]=useState<Card|null>(null),[reopening,setReopening]=useState<Card|null>(null),[addingUser,setAddingUser]=useState(false),[emailPreview,setEmailPreview]=useState(false),[busy,setBusy]=useState(false),[settings,setSettings]=useState<{smtp_ready:boolean;connected:boolean}>({smtp_ready:false,connected:configured});
 const repo=useMemo(()=>user?(demo?demoRepository(user):liveRepository()):null,[user,demo]);
 useEffect(()=>{currentProfile().then(setUser).catch(()=>{}).finally(()=>setChecking(false));},[]);
 useEffect(()=>{window.scrollTo(0,0);},[view,user?.id]);
 useEffect(()=>{if(user?.role!=='admin'&&view==='team')setView('board');},[user?.role,view]);
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('ti-flow-theme',theme);},[theme]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(null),6000);return()=>clearTimeout(t);},[toast]);
 function notify(text:string,error=false){setToast({text,error});}
 async function reload(){if(!repo)return;setLoading(true);try{const next=await repo.load();setData(next);setDrawer(current=>current&&current!=='new'?next.cards.find(c=>c.id===current.id)??null:current);}catch(e){notify(message(e),true);}finally{setLoading(false);}}
 useEffect(()=>{if(repo&&!user?.must_change_password){void reload();if(!demo)gateway('health',{},true).then(setSettings).catch(()=>{});}},[repo]);
 useEffect(()=>{if(demo||!supabase||!user||user.must_change_password)return;const channel=supabase.channel('ti-flow-board').on('postgres_changes',{event:'*',schema:'public',table:'activities'},()=>{void reload();}).on('postgres_changes',{event:'*',schema:'public',table:'profiles'},()=>{void currentProfile().then(p=>{if(!p?.active){setUser(null);void supabase?.auth.signOut({scope:'local'});}else setUser(p);});}).subscribe();return()=>{void supabase!.removeChannel(channel);};},[demo,user?.id]);
 async function mutate(fn:()=>Promise<unknown>,success?:string){setBusy(true);try{await fn();await reload();if(success)notify(success);return true;}catch(e){notify(message(e),true);await reload();return false;}finally{setBusy(false);}}
 async function update(card:Card,patch:CardPatch){return mutate(()=>repo!.update(card,patch));}
 async function logout(){if(!demo)await supabase?.auth.signOut({scope:'local'});setUser(null);setDemo(false);setData({cards:[],profiles:[],events:[]});setDrawer(null);setView('board');}
 const active=data.cards.filter(c=>c.status!=='completed');
 const filtered=data.cards.filter(c=>{if(view==='archive'&&((archiveStart&&dayInZone(c.closed_at)<archiveStart)||(archiveEnd&&dayInZone(c.closed_at)>archiveEnd)))return false;const owner=data.profiles.find(p=>p.id===c.assignee_id);return (!query||`${c.code} ${c.title} ${c.description} ${owner?.full_name??''}`.toLowerCase().includes(query.toLowerCase()))&&(assignee==='all'||c.assignee_id===(assignee==='mine'?user?.id:assignee))&&(priority==='all'||c.priority===priority);});
 const ordered=[...filtered].sort((a,b)=>sort==='priority'?priorities.indexOf(a.priority)-priorities.indexOf(b.priority):sort==='due'?a.due_date.localeCompare(b.due_date):a.position-b.position||a.number-b.number);
 const counts=dashboardCounts(data.cards);
 const sensors=useSensors(useSensor(PointerSensor,{activationConstraint:{distance:6}}),useSensor(KeyboardSensor,{coordinateGetter:sortableKeyboardCoordinates}));
 async function dragEnd(event:DragEndEvent){if(!repo||!user)return;const {active:dragged,over}=event;if(!over||dragged.id===over.id)return;const card=data.cards.find(c=>c.id===dragged.id);if(!card||!canEdit(user,card))return;const target=data.cards.find(c=>c.id===over.id),status=target?.status??String(over.id) as Status;if(status==='completed'||!statuses.some(s=>s.id===status))return;const column=ordered.filter(c=>c.status===status&&c.id!==card.id),index=target?column.findIndex(c=>c.id===target.id):column.length;const before=column[index-1]?.position??((column[0]?.position??0)-2048),after=column[index]?.position??before+2048;await update(card,{status,position:(before+after)/2});setSort('manual');}
 if(checking)return <div className="app-loading"><Brand/><LoaderCircle className="spin"/><p>Preparando seu espaço…</p></div>;
 if(recovery)return <RecoveryScreen token={recovery} onDone={()=>{window.history.replaceState({},'',window.location.pathname);setRecovery(null);setUser(null);}}/>;
 if(!user)return <LoginScreen onLogin={p=>{setDemo(false);setUser(p);}} onDemo={()=>{setDemo(true);setUser(makeDemo().profiles[0]);}}/>;
 if(user.must_change_password&&!demo)return <PasswordScreen onDone={()=>{setUser(null);notify('Senha alterada. Entre com sua nova senha.');}}/>;
 const title=view==='board'?'Quadro de atividades':view==='dashboard'?'Visão geral':view==='archive'?'Histórico de atividades':view==='team'?'Nossa equipe':'Configurações';
 return <div className="app-shell"><aside className={`sidebar ${mobile?'sidebar-open':''}`}><div className="sidebar-brand"><Brand/><button className="icon-btn mobile-only" aria-label="Fechar menu" onClick={()=>setMobile(false)}><X size={18}/></button></div><div className="workspace"><span className="workspace-icon"><Activity size={19}/></span><div><strong>Automações TI</strong><small>Workspace da equipe</small></div><ChevronDown size={14}/></div><div className="nav-caption">WORKSPACE</div><nav>{navigation.filter(n=>n.id!=='team'||user.role==='admin').map(n=><button key={n.id} className={`nav-item ${view===n.id?'nav-active':''}`} onClick={()=>{setView(n.id);setMobile(false);setQuery('');}}><n.icon size={19}/><span>{n.label}</span>{n.id==='board'&&<b>{active.length}</b>}</button>)}</nav><div className="sidebar-note"><span className="note-orbit"><CheckCheck size={22}/></span><strong>Um passo de cada vez.</strong><p>Grandes entregas começam com atividades bem organizadas.</p><span className="note-line"/></div><div className="sidebar-bottom"><button className={`nav-item ${view==='settings'?'nav-active':''}`} onClick={()=>{setView('settings');setMobile(false);}}><Settings2 size={18}/>Configurações</button><div className="theme-switch"><span>Aparência</span><button className={theme==='light'?'selected':''} aria-label="Usar tema claro" onClick={()=>setTheme('light')}><Sun size={15}/></button><button className={theme==='dark'?'selected':''} aria-label="Usar tema escuro" onClick={()=>setTheme('dark')}><Moon size={15}/></button></div><div className="sidebar-profile"><Avatar profile={user}/><div><strong>{user.full_name}</strong><small>{roleLabel[user.role]}</small></div><button className="icon-btn" aria-label="Sair da conta" onClick={logout}><LogOut size={16}/></button></div></div></aside>{mobile&&<div className="sidebar-scrim" onClick={()=>setMobile(false)}/>}
 <div className="main-wrap"><header className="topbar"><div className="breadcrumbs"><button className="icon-btn mobile-only" aria-label="Abrir menu" onClick={()=>setMobile(true)}><Menu size={21}/></button><span>Workspace</span><ChevronRight size={13}/><strong>{title}</strong></div><div className="topbar-right"><span className="today-label"><CalendarDays size={14}/>{new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',timeZone:'America/Sao_Paulo'}).format(new Date())}</span><span className="topbar-separator"/><button className="icon-btn" aria-label="Atualizar atividades" onClick={reload}><RefreshCw size={17} className={loading?'spin':''}/></button><Avatar profile={user} size="small"/></div></header>
 {demo&&<div className="demo-banner"><div><span className="demo-pulse"/><strong>Demonstração</strong><span>Dados fictícios · alterações salvas neste navegador</span></div><button onClick={logout}>Voltar ao login <ArrowRight size={13}/></button></div>}
 <main className="main-content"><div className="page-heading"><div><div className="eyebrow page-eyebrow">{view==='board'?'ORGANIZE. ACOMPANHE. RESOLVA.':view==='dashboard'?'O TRABALHO EM PERSPECTIVA':view==='archive'?'CADA ENTREGA TEM UMA HISTÓRIA':view==='team'?'PESSOAS QUE FAZEM ACONTECER':'DO SEU JEITO'}</div><h1>{title}<span className="heading-dot">.</span></h1><p>{view==='board'?'Uma visão clara do que precisa acontecer.':view==='dashboard'?`Olá, ${user.full_name.split(' ')[0]}. Veja como estão as entregas da equipe.`:view==='archive'?'Entregas preservadas, contexto sempre à mão.':view==='team'?'Gerencie os acessos e conecte sua equipe.':'Seu ambiente, suas preferências e integrações.'}</p></div><div className="heading-actions">{view==='board'&&<div className="team-stack">{data.profiles.filter(p=>p.active&&!p.must_change_password).slice(0,4).map(p=><Avatar key={p.id} profile={p} size="small"/>)}<span>{data.profiles.filter(p=>p.active&&!p.must_change_password).length} na equipe</span></div>}{(view==='board'||view==='dashboard')&&<Button icon={Plus} onClick={()=>{setNewStatus('pending');setDrawer('new');}}>Nova atividade</Button>}{view==='team'&&<Button icon={Plus} onClick={()=>setAddingUser(true)}>Novo usuário</Button>}</div></div>
 {(view==='board'||view==='dashboard')&&<div className="stats-row"><Stat icon={LayoutGrid} label="Atividades abertas" value={counts.active} tone="blue" foot="Em todas as etapas"/><Stat icon={Clock3} label="Em andamento" value={active.filter(c=>c.status==='in_progress').length} tone="purple" foot="A equipe está cuidando"/><Stat icon={History} label="Pendentes de terceiros" value={counts.third} tone="amber" foot="Aguardando um retorno"/><Stat icon={CheckCircle2} label="Atividades concluídas" value={counts.completed} tone="green" foot="Entregas registradas"/></div>}
 {(view==='board'||view==='archive')&&<><div className="board-toolbar"><div className="search-field"><Search size={17}/><input aria-label="Pesquisar atividades" placeholder="Buscar por título, ID ou responsável…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button className="icon-btn" aria-label="Limpar busca" onClick={()=>setQuery('')}><X size={14}/></button>}<span className="search-key">⌕</span></div><div className="toolbar-actions"><button className={`filter-pill ${assignee==='mine'?'pill-active':''}`} onClick={()=>setAssignee(assignee==='mine'?'all':'mine')}><Avatar profile={user} size="small"/>Minhas atividades</button><button className={`filter-pill ${showFilters||priority!=='all'||!['all','mine'].includes(assignee)?'pill-active':''}`} onClick={()=>setShowFilters(!showFilters)}><SlidersHorizontal size={15}/>Filtros{(priority!=='all'||assignee!=='all')&&<span className="filter-count">{Number(priority!=='all')+Number(assignee!=='all')}</span>}</button><div className="sort-control"><ArrowDown size={14}/><select aria-label="Ordenar atividades" value={sort} onChange={e=>setSort(e.target.value)}><option value="manual">Ordem manual</option><option value="priority">Prioridade</option><option value="due">Prazo de entrega</option></select></div></div></div>{showFilters&&<div className="filters-panel"><label>Responsável<select value={assignee} onChange={e=>setAssignee(e.target.value)}><option value="all">Toda a equipe</option><option value="mine">Minhas atividades</option>{data.profiles.map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label><label>Prioridade<select value={priority} onChange={e=>setPriority(e.target.value)}><option value="all">Todas as prioridades</option>{priorities.map(p=><option key={p} value={p}>{priorityLabel[p]}</option>)}</select></label>{view==='archive'&&<><label>Finalizado a partir de<input type="date" value={archiveStart} onChange={e=>setArchiveStart(e.target.value)}/></label><label>Finalizado até<input type="date" min={archiveStart} value={archiveEnd} onChange={e=>setArchiveEnd(e.target.value)}/></label></>}<button className="text-btn" onClick={()=>{setAssignee('all');setPriority('all');setQuery('');setArchiveStart('');setArchiveEnd('');}}>Limpar filtros</button></div>}</>}
 {view==='board'&&<><div className="board-caption"><span><span className="live-dot"/>{filtered.filter(c=>c.status!=='completed').length} atividades no quadro</span><span><GripVertical size={13}/> Arraste pelo ícone para mover</span></div><DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={dragEnd}><div className="kanban-grid">{statuses.map(s=><Column key={s.id} status={s} cards={ordered.filter(c=>c.status===s.id)} profiles={data.profiles} user={user} onOpen={setDrawer} onAdd={()=>{setNewStatus(s.id);setDrawer('new');}}/>)}</div></DndContext><div className="board-footer"><ShieldCheck size={13}/><span>Atividades concluídas saem do quadro e ficam preservadas no histórico.</span><button onClick={()=>setView('archive')}>Ver histórico <ArrowRight size={13}/></button></div></>}
 {view==='dashboard'&&<Dashboard data={data} user={user} onOpen={setDrawer} onBoard={()=>setView('board')}/>}
 {view==='archive'&&<Archive cards={ordered.filter(c=>c.status==='completed')} profiles={data.profiles} onOpen={setDrawer}/>}
 {view==='team'&&user.role==='admin'&&<Team profiles={data.profiles} user={user} demo={demo} onAdd={()=>setAddingUser(true)} onRole={(p,r)=>void mutate(()=>repo!.setUserRole(p.id,r),'Perfil atualizado.')} onToggle={p=>void mutate(()=>repo!.setUserActive(p.id,!p.active),p.active?'Usuário desativado.':'Usuário ativado.')} onResend={p=>void mutate(()=>repo!.resend(p.id),'Nova senha programada para envio.')} busy={busy}/>}
 {view==='settings'&&<Settings theme={theme} setTheme={setTheme} demo={demo} settings={settings} user={user} onPreview={()=>setEmailPreview(true)} onPassword={()=>setChangingPassword(true)} onReset={()=>void mutate(async()=>{await repo?.reset?.();},'Demonstração restaurada.')}/>}
 <footer className="app-footer"><Brand small/><span>Clareza para planejar. Espaço para realizar.</span><span>Automações TI</span></footer></main></div>
 {toast&&<div className={`toast ${toast.error?'toast-error':''}`} role="status">{toast.error?<Bell size={18}/>:<CheckCircle2 size={18}/>}<span>{toast.text}</span><button className="icon-btn" aria-label="Fechar aviso" onClick={()=>setToast(null)}><X size={15}/></button></div>}
 {drawer&&<CardDrawer card={drawer} initialStatus={newStatus} user={user} profiles={data.profiles} events={data.events} cards={data.cards} busy={busy} onClose={()=>setDrawer(null)} onSave={async input=>{if(drawer==='new'){let created:Card|undefined;const ok=await mutate(async()=>{created=await repo!.create(input);},'Atividade criada.');if(ok&&created)setDrawer(created);}else{const ok=await mutate(()=>repo!.update(drawer,input),'Atividade atualizada.');if(ok)setDrawer(null);}}} onPatch={update} onComplete={setConfirmClose} onReopen={setReopening} onNavigate={setDrawer} onUpload={async(card,file)=>{await mutate(async()=>{const attachment=await repo!.upload(card,file);await repo!.update(card,{attachments:[...card.attachments,attachment]});},'Arquivo anexado.');}} onDownload={async a=>{try{await repo!.download(a);}catch(e){notify(message(e),true);}}}/>}
 {confirmClose&&<Modal title="Concluir atividade?" subtitle={confirmClose.code} onClose={()=>setConfirmClose(null)}><div className="confirm-illustration"><CheckCheck size={30}/></div><p className="modal-copy"><strong>{confirmClose.title}</strong></p><p className="modal-copy">A atividade sairá do quadro e ficará preservada no histórico, disponível somente para consulta. Uma reabertura criará um novo card vinculado a este.</p><div className="modal-actions"><Button kind="secondary" onClick={()=>setConfirmClose(null)}>Voltar</Button><Button icon={Check} disabled={busy} onClick={async()=>{const ok=await mutate(()=>repo!.complete(confirmClose),'Atividade concluída e preservada no histórico.');if(ok){setConfirmClose(null);setDrawer(null);}}}>Concluir atividade</Button></div></Modal>}
 {reopening&&<ReopenModal card={reopening} user={user} profiles={data.profiles} busy={busy} onClose={()=>setReopening(null)} onSubmit={async(reason,start,due,owner)=>{let created:Card|undefined;const ok=await mutate(async()=>{created=await repo!.reopen(reopening,reason,start,due,owner);},'Nova atividade criada, com vínculo permanente ao original.');if(ok){setReopening(null);if(created)setDrawer(created);}}}/>}
 {addingUser&&<UserModal demo={demo} smtpReady={settings.smtp_ready} profiles={data.profiles} busy={busy} onClose={()=>setAddingUser(false)} onSubmit={async input=>{const ok=await mutate(()=>repo!.createUser(input),demo?'Usuário fictício criado. Nenhum e-mail foi enviado.':'Usuário criado. Boas-vindas na fila e senha enviada cerca de 2 minutos depois.');if(ok)setAddingUser(false);}}/>}
 {emailPreview&&<EmailPreview onClose={()=>setEmailPreview(false)}/>}
 {changingPassword&&<ChangePasswordModal onClose={()=>setChangingPassword(false)} onDone={async()=>{setChangingPassword(false);await logout();}}/>}
 </div>;
}

function Stat({icon:Icon,label,value,tone,foot}:{icon:LucideIcon;label:string;value:number;tone:string;foot:string}) {return <div className="stat-card"><div className="stat-top"><span>{label}</span><span className={`stat-icon tone-${tone}`}><Icon size={17}/></span></div><div className="stat-value">{String(value).padStart(2,'0')}<span className={`stat-mini tone-${tone}`}><span/><span/><span/><span/><span/></span></div><div className="stat-foot">{tone==='green'&&<Check size={12}/>} {foot}</div></div>;}
function Column({status,cards,profiles,user,onOpen,onAdd}:{status:typeof statuses[number];cards:Card[];profiles:Profile[];user:Profile;onOpen:(c:Card)=>void;onAdd:()=>void}) {const {setNodeRef,isOver}=useDroppable({id:status.id});return <section ref={setNodeRef} className={`kanban-column column-${status.color} ${isOver?'column-over':''}`} aria-label={status.label}><div className="column-header"><div><span className="column-dot"/><h2>{status.label}</h2><span className="column-count">{cards.length}</span></div><button className="icon-btn" aria-label={`Criar atividade em ${status.label}`} onClick={onAdd}><Plus size={16}/></button></div><p className="column-hint">{status.hint}</p><div className="column-cards"><SortableContext items={cards.map(c=>c.id)} strategy={verticalListSortingStrategy}>{cards.map(c=><TaskCard key={c.id} card={c} profile={profiles.find(p=>p.id===c.assignee_id)} editable={canEdit(user,c)} onOpen={()=>onOpen(c)}/>)}</SortableContext>{cards.length===0&&<div className="column-empty"><LayoutGrid size={22}/><span>Nenhuma atividade por aqui</span><button onClick={onAdd}>Criar uma atividade <Plus size={12}/></button></div>}</div><button className="column-add" onClick={onAdd}><Plus size={15}/>Adicionar atividade</button></section>;}
function TaskCard({card,profile,editable,onOpen}:{card:Card;profile?:Profile;editable:boolean;onOpen:()=>void}) {const {attributes,listeners,setNodeRef,transform,transition,isDragging}=useSortable({id:card.id,disabled:!editable});const done=card.checklist.filter(i=>i.done).length,late=overdue(card),dueToday=card.due_date===today();return <article ref={setNodeRef} style={{transform:CSS.Transform.toString(transform),transition}} className={`task-card ${isDragging?'task-dragging':''}`}><div className="task-top"><PriorityTag value={card.priority}/><button className="drag-handle" aria-label={`Mover ${card.code}`} disabled={!editable} {...attributes} {...listeners}><GripVertical size={16}/></button></div><button className="task-body" onClick={onOpen}><span className="task-code">{card.code}{card.parent_id&&<Link2 size={11}/>}</span><h3>{card.title}</h3><p>{card.description}</p></button>{card.checklist.length>0&&<div className="task-progress"><span><ListChecks size={13}/>{done}/{card.checklist.length}</span><div><i style={{width:`${done/card.checklist.length*100}%`}}/></div></div>}<div className="task-bottom"><span className={`task-due ${late?'due-late':dueToday?'due-today':''}`}><CalendarDays size={12}/>{shortDate(card.due_date)}{late&&<i/>}</span><div className="task-meta">{card.comments.length>0&&<span><MessageSquare size={12}/>{card.comments.length}</span>}{card.attachments.length>0&&<span><Paperclip size={12}/>{card.attachments.length}</span>}<Avatar profile={profile} size="small"/></div></div></article>;}

function Dashboard({data,user,onOpen,onBoard}:{data:DataSet;user:Profile;onOpen:(c:Card)=>void;onBoard:()=>void}) {const [owner,setOwner]=useState('all'),[period,setPeriod]=useState('30');const filtered=data.cards.filter(c=>(owner==='all'||c.assignee_id===owner)&&(period==='all'||dayInZone(c.created_at)>=dateOffset(-Number(period))));const active=filtered.filter(c=>c.status!=='completed'),late=active.filter(overdue);const completed=filtered.filter(c=>c.status==='completed').length;const total=filtered.length;return <><div className="dashboard-filter"><span><span className="live-dot"/>Panorama da equipe</span><div><select aria-label="Responsável no dashboard" value={owner} onChange={e=>setOwner(e.target.value)}><option value="all">Toda a equipe</option>{data.profiles.map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select><select aria-label="Período no dashboard" value={period} onChange={e=>setPeriod(e.target.value)}><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option><option value="all">Todo o período</option></select></div></div><div className="dashboard-grid"><section className="panel distribution"><div className="panel-header"><div><h2>O ritmo das entregas</h2><p>Distribuição das atividades no período</p></div><BarChart3 size={19}/></div><div className="distribution-body"><div className="donut" style={{background:`conic-gradient(var(--blue) 0 ${total?active.filter(c=>c.status==='in_progress').length/total*100:0}%, var(--amber) 0 ${total?active.filter(c=>c.status!=='pending').length/total*100:0}%, var(--green) 0 ${total?(total-active.filter(c=>c.status==='pending').length)/total*100:0}%, var(--chart-track) 0 100%)`}}><div><strong>{total}</strong><span>atividades</span></div></div><div className="chart-legend">{([...statuses.map(s=>({id:s.id,label:s.label})),{id:'completed',label:'Concluídas'}]).map(s=><div key={s.id}><span className={`legend-dot legend-${s.id}`}/><span>{s.label}</span><strong>{filtered.filter(c=>c.status===s.id).length}</strong></div>)}</div></div><div className="panel-note"><CheckCircle2 size={15}/>{total?Math.round(completed/total*100):0}% das atividades do período já foram concluídas.</div></section><section className="panel priorities-panel"><div className="panel-header"><div><h2>Prioridades em foco</h2><p>Atividades abertas por prioridade</p></div><Filter size={18}/></div><div className="priority-chart">{priorities.map(p=>{const n=active.filter(c=>c.priority===p).length;return <div key={p}><div><PriorityTag value={p}/><strong>{n}</strong></div><span className={`bar-track bar-${p}`}><i style={{width:`${active.length?n/active.length*100:0}%`}}/></span></div>;})}</div></section><section className="panel attention-panel"><div className="panel-header"><div><h2>Precisam de atenção <span className="tiny-count">{late.length}</span></h2><p>Atividades com prazo ultrapassado</p></div><Clock3 size={19}/></div>{late.length===0?<Empty icon={CheckCircle2} title="Prazos em dia" text="Nenhuma atividade atrasada neste período."/>:<div className="attention-list">{late.slice(0,5).map(c=><button key={c.id} onClick={()=>onOpen(c)}><span className="attention-symbol"><Clock3 size={17}/></span><div><small>{c.code}</small><strong>{c.title}</strong></div><span className="due-late">{shortDate(c.due_date)}</span><ChevronRight size={15}/></button>)}</div>}</section><section className="panel workload-panel"><div className="panel-header"><div><h2>Distribuição da equipe</h2><p>Atividades abertas por responsável</p></div><Users size={18}/></div><div className="workload-list">{data.profiles.filter(p=>p.active&&!p.must_change_password&&(owner==='all'||p.id===owner)).map(p=>{const n=active.filter(c=>c.assignee_id===p.id).length;return <div key={p.id}><Avatar profile={p} size="small"/><span>{p.full_name}{p.id===user.id&&<small> você</small>}</span><strong>{n}</strong><span className="workload-bar"><i style={{width:`${Math.min(100,n/Math.max(1,active.length)*100)}%`}}/></span></div>;})}</div></section></div><section className="dashboard-bottom"><div><span className="note-orbit"><LayoutGrid size={23}/></span><div><h3>Da visão geral à próxima ação.</h3><p>Seu quadro tem tudo o que a equipe precisa para seguir em frente.</p></div></div><Button kind="secondary" icon={ArrowRight} onClick={onBoard}>Abrir quadro</Button></section></>;}

function Archive({cards,profiles,onOpen}:{cards:Card[];profiles:Profile[];onOpen:(c:Card)=>void}) {return <section className="panel archive-panel"><div className="panel-header"><div><h2>Entregas concluídas <span className="tiny-count">{cards.length}</span></h2><p>Registros preservados. Reabrir cria uma nova atividade vinculada.</p></div><ShieldCheck size={20}/></div>{!cards.length?<Empty icon={History} title="Nenhum registro encontrado" text="As atividades concluídas aparecerão aqui. Tente ajustar os filtros."/>:<div className="table-scroll"><table><thead><tr><th>Atividade</th><th>Responsável</th><th>Prioridade</th><th>Finalização</th><th>Status</th><th/></tr></thead><tbody>{cards.map(c=><tr key={c.id}><td><button className="table-title" onClick={()=>onOpen(c)}><small>{c.code}{c.parent_id&&<Link2 size={11}/>}</small><strong>{c.title}</strong></button></td><td><span className="person-cell"><Avatar profile={profiles.find(p=>p.id===c.assignee_id)} size="small"/>{profiles.find(p=>p.id===c.assignee_id)?.full_name}</span></td><td><PriorityTag value={c.priority}/></td><td>{c.closed_at?dateTime(c.closed_at):'—'}</td><td><StatusTag value="completed"/></td><td><button className="icon-btn" aria-label={`Consultar ${c.code}`} onClick={()=>onOpen(c)}><ArrowUpRight size={17}/></button></td></tr>)}</tbody></table></div>}</section>;}

function Team({profiles,user,demo,onAdd,onToggle,onResend,onRole,busy}:{profiles:Profile[];user:Profile;demo:boolean;onAdd:()=>void;onToggle:(p:Profile)=>void;onResend:(p:Profile)=>void;onRole:(p:Profile,r:Role)=>void;busy:boolean}) {return <><div className="team-summary"><div><Users size={18}/><strong>{profiles.length}</strong> pessoas na equipe</div><div><span className="live-dot"/><strong>{profiles.filter(p=>p.active).length}</strong> acessos ativos</div><div><LockKeyhole size={15}/>{profiles.filter(p=>p.must_change_password).length} aguardando primeiro acesso</div></div><section className="panel"><div className="panel-header"><div><h2>Acessos da equipe</h2><p>Somente administradores gerenciam os usuários.</p></div><ShieldCheck size={20}/></div>{!profiles.length?<Empty icon={Users} title="Sua equipe começa aqui" text="Cadastre o primeiro integrante para começar." action={<Button icon={Plus} onClick={onAdd}>Novo usuário</Button>}/>:<div className="table-scroll"><table><thead><tr><th>Pessoa</th><th>Login</th><th>Perfil</th><th>Situação</th><th>E-mails de acesso</th><th>Ações</th></tr></thead><tbody>{profiles.map(p=><tr key={p.id}><td><span className="person-cell"><Avatar profile={p}/><span><strong>{p.full_name}{p.id===user.id&&<small className="you-tag"> você</small>}</strong><small>{p.email??''}</small></span></span></td><td><code>{p.username}</code></td><td><select className={`role-select role-${p.role}`} aria-label={`Perfil de ${p.full_name}`} value={p.role} disabled={busy||p.id===user.id} onChange={e=>onRole(p,e.target.value as Role)}><option value="admin">Administrador</option><option value="manager">Gestor</option><option value="technician">Técnico</option></select></td><td><span className={`status-tag ${p.active?'status-completed':'status-pending'}`}><i/>{p.active?'Ativo':'Desativado'}</span>{p.must_change_password&&<small className="cell-note">Troca de senha pendente</small>}</td><td>{demo?<span className="cell-note">{p.welcome_status==='simulated'?'Simulação · não enviados':'Dados fictícios'}</span>:<span className="email-states"><small>Boas-vindas: {p.welcome_status??'—'}</small><small>Senha: {p.password_status??'—'}</small></span>}</td><td><div className="table-actions"><button className="icon-btn" aria-label={`Reenviar senha para ${p.full_name}`} disabled={busy||!p.active||demo} onClick={()=>onResend(p)}><Mail size={16}/></button><button className="text-btn" disabled={busy||p.id===user.id} onClick={()=>onToggle(p)}>{p.active?'Desativar':'Ativar'}</button></div></td></tr>)}</tbody></table></div>}</section><div className="information-row"><Mail size={20}/><p><strong>Dois e-mails para um começo organizado.</strong> O novo usuário recebe as boas-vindas primeiro. A senha temporária é enviada aproximadamente 2 minutos depois.</p></div></>;}

function Settings({theme,setTheme,demo,settings,user,onPreview,onPassword,onReset}:{theme:string;setTheme:(t:string)=>void;demo:boolean;settings:{smtp_ready:boolean;connected:boolean};user:Profile;onPreview:()=>void;onPassword:()=>void;onReset:()=>void}) {return <div className="settings-grid"><section className="panel"><div className="panel-header"><div><h2>Aparência</h2><p>Um espaço confortável para trabalhar.</p></div><Sun size={20}/></div><div className="theme-options">{[{id:'light',label:'Claro',icon:Sun},{id:'dark',label:'Escuro',icon:Moon}].map(t=><button key={t.id} onClick={()=>setTheme(t.id)} className={`theme-option ${theme===t.id?'theme-option-active':''}`}><span className={`theme-mini mini-${t.id}`}><i/><div><span/><span/><span/></div></span><span><t.icon size={15}/>{t.label}{theme===t.id&&<CheckCircle2 size={16}/>}</span></button>)}</div></section><section className="panel"><div className="panel-header"><div><h2>Meu perfil</h2><p>Seu acesso ao workspace.</p></div><ShieldCheck size={19}/></div><div className="profile-settings"><Avatar profile={user} size="large"/><div><h3>{user.full_name}</h3><p>{user.username}</p><span className="role-tag">{roleLabel[user.role]}</span>{!demo&&<button className="text-btn profile-password" onClick={onPassword}><LockKeyhole size={13}/>Alterar minha senha</button>}</div></div></section><section className="panel integrations-panel"><div className="panel-header"><div><h2>Ambiente e integrações</h2><p>Conexões necessárias para o uso da equipe.</p></div><Monitor size={19}/></div><div className="integration-row"><span className="integration-icon"><Activity size={20}/></span><div><strong>Supabase</strong><p>Autenticação, atividades e arquivos privados.</p></div><span className={`connection-badge ${settings.connected?'connection-ok':''}`}>{settings.connected?'Conectado':'Configuração pendente'}</span></div><div className="integration-row"><span className="integration-icon"><Mail size={20}/></span><div><strong>E-mails transacionais</strong><p>Boas-vindas e senha temporária com intervalo de 2 minutos.</p></div><span className={`connection-badge ${settings.smtp_ready?'connection-ok':''}`}>{settings.smtp_ready?'Configurado':'Configuração pendente'}</span></div><div className="integration-footer"><span><LockKeyhole size={14}/> Credenciais configuradas apenas no servidor.</span><button className="text-btn" onClick={onPreview}>Prévia dos e-mails <ArrowUpRight size={14}/></button></div></section><section className="panel settings-rules"><div className="panel-header"><div><h2>Regras do workspace</h2><p>Consistência em cada atividade.</p></div><ListChecks size={19}/></div><div><p><CheckCircle2 size={15}/> Cards concluídos ficam somente para consulta.</p><p><Link2 size={15}/> Reaberturas mantêm vínculo permanente ao original.</p><p><LockKeyhole size={15}/> Troca obrigatória de senha no primeiro acesso.</p><p><CalendarDays size={15}/> Datas no fuso de São Paulo.</p></div></section>{demo&&<section className="demo-reset"><div><h3>Ambiente de demonstração</h3><p>Restaure os dados fictícios para explorar novamente.</p></div><Button kind="secondary" icon={RefreshCw} onClick={onReset}>Restaurar demonstração</Button></section>}</div>;}

function CardDrawer({card,initialStatus,user,profiles,events,cards,busy,onClose,onSave,onPatch,onComplete,onReopen,onNavigate,onUpload,onDownload}:{card:Card|'new';initialStatus:Status;user:Profile;profiles:Profile[];events:AuditEvent[];cards:Card[];busy:boolean;onClose:()=>void;onSave:(i:CardInput)=>Promise<void>;onPatch:(c:Card,p:CardPatch)=>Promise<boolean>;onComplete:(c:Card)=>void;onReopen:(c:Card)=>void;onNavigate:(c:Card)=>void;onUpload:(c:Card,f:File)=>Promise<void>;onDownload:(a:Card['attachments'][number])=>Promise<void>}) {
 const dialogRef=useDialogFocus(onClose);
 const isNew=card==='new',existing=isNew?null:card;const [input,setInput]=useState<CardInput>(isNew?{...defaultInput(user),status:initialStatus}:card),[tab,setTab]=useState('details'),[checkText,setCheckText]=useState(''),[comment,setComment]=useState('');
 useEffect(()=>{setInput(card==='new'?{...defaultInput(user),status:initialStatus}:card);setTab('details');},[existing?.id]);
 useEffect(()=>{if(existing)setInput(existing);},[existing?.version]);

 const editable=isNew||!!existing&&canEdit(user,existing);const owner=profiles.find(p=>p.id===input.assignee_id),parent=existing?.parent_id?cards.find(c=>c.id===existing.parent_id):null,related=existing?cards.filter(c=>c.parent_id===existing.id):[];
 function field<K extends keyof CardInput>(k:K,value:CardInput[K]){setInput(p=>({...p,[k]:value}));}
 return <div className="drawer-backdrop" onClick={onClose}><section ref={dialogRef} className="drawer" role="dialog" aria-modal="true" aria-label={isNew?'Nova atividade':existing!.code} onClick={e=>e.stopPropagation()}><header className="drawer-header"><span><LayoutGrid size={16}/>{isNew?'NOVA ATIVIDADE':existing!.code}</span><div>{existing&&<PriorityTag value={existing.priority}/>}<button className="icon-btn" aria-label="Fechar atividade" onClick={onClose}><X size={21}/></button></div></header><div className="drawer-title"><span className="eyebrow">{isNew?'TRANSFORME UMA IDEIA EM PRÓXIMA AÇÃO':existing?.status==='completed'?'ENTREGA PRESERVADA':'CADA ETAPA IMPORTA'}</span><h2>{isNew?'O que vamos resolver?':existing!.title}</h2>{existing&&<div className="drawer-subtitle"><StatusTag value={existing.status}/><span>Criada em {shortDate(dayInZone(existing.created_at))}</span></div>}</div>{existing?.status==='completed'&&<div className="closed-notice"><ShieldCheck size={18}/><div><strong>Atividade concluída · somente consulta</strong><span>Finalizada em {dateTime(existing.closed_at!)}. O registro original permanece intacto.</span></div></div>}{parent&&<div className="parent-link"><Link2 size={16}/><div>Continuação de <button onClick={()=>onNavigate(parent)}>{parent.code} <ArrowUpRight size={12}/></button><small>{existing?.reopen_reason}</small></div><LockKeyhole size={13}/></div>}{!isNew&&<nav className="drawer-tabs">{[{id:'details',label:'Detalhes',icon:FileText},{id:'checklist',label:'Checklist',icon:ListChecks},{id:'comments',label:'Comentários',icon:MessageSquare},{id:'events',label:'Histórico',icon:History}].map(t=><button key={t.id} className={tab===t.id?'tab-active':''} onClick={()=>setTab(t.id)}><t.icon size={15}/>{t.label}{t.id==='comments'&&existing!.comments.length>0&&<small>{existing!.comments.length}</small>}</button>)}</nav>}
 <div className="drawer-content">{tab==='details'&&<form id="card-form" onSubmit={e=>{e.preventDefault();void onSave(input);}}><label>Título da atividade<input value={input.title} onChange={e=>field('title',e.target.value)} placeholder="Ex.: Atualizar os switches do escritório" maxLength={180} required disabled={!editable}/></label><label>Descrição<textarea value={input.description} onChange={e=>field('description',e.target.value)} placeholder="Descreva o contexto, o que precisa ser feito e o resultado esperado…" rows={5} maxLength={20000} disabled={!editable}/></label><div className="form-grid"><label>Responsável<select value={input.assignee_id} onChange={e=>field('assignee_id',e.target.value)} disabled={!editable||user.role==='technician'} required>{profiles.filter(p=>p.active&&!p.must_change_password||p.id===input.assignee_id).map(p=><option key={p.id} value={p.id}>{p.full_name}{!p.active?' (desativado)':''}</option>)}</select></label><label>Prioridade<select value={input.priority} onChange={e=>field('priority',e.target.value as Priority)} disabled={!editable}>{priorities.map(p=><option key={p} value={p}>{priorityLabel[p]}</option>)}</select></label><label>Data inicial<input type="date" value={input.start_date} onChange={e=>field('start_date',e.target.value)} required disabled={!editable}/></label><label>Término previsto<input type="date" value={input.due_date} min={input.start_date} onChange={e=>field('due_date',e.target.value)} required disabled={!editable}/></label></div><label>Status<select value={input.status} onChange={e=>field('status',e.target.value as Status)} disabled={!editable}>{statuses.map(s=><option key={s.id} value={s.id}>{s.label}</option>)}{existing?.status==='completed'&&<option value="completed">Concluído</option>}</select></label>{existing&&<div className="attachments"><div className="section-label"><span><Paperclip size={16}/>Anexos <small>{existing.attachments.length}</small></span>{editable&&<label className="text-btn upload-label"><Plus size={14}/>Anexar arquivo<input type="file" hidden disabled={busy} accept=".pdf,.png,.jpg,.jpeg,.webp,.gif,.txt,.csv,.doc,.docx,.xls,.xlsx,.ppt,.pptx" onChange={e=>{const f=e.target.files?.[0];if(f)void onUpload(existing,f);e.target.value='';}}/></label>}</div>{existing.attachments.length?existing.attachments.map(a=><button key={a.id} type="button" className="attachment-item" onClick={()=>void onDownload(a)}><span><FileText size={20}/></span><div><strong>{a.name}</strong><small>{formatSize(a.size)} · {dateTime(a.created_at)}</small></div><Download size={16}/></button>):<div className="attachment-empty"><Paperclip size={18}/><span>Nenhum arquivo anexado</span><small>Até 10 MB · PDF, imagens, texto e Office</small></div>}</div>}{related.length>0&&<div className="related-cards"><div className="section-label"><span><Link2 size={16}/>Continuações vinculadas</span></div>{related.map(c=><button key={c.id} type="button" onClick={()=>onNavigate(c)}><span>{c.code}</span><strong>{c.title}</strong><StatusTag value={c.status}/><ChevronRight size={15}/></button>)}</div>}</form>}
 {tab==='checklist'&&existing&&<div className="checklist-panel"><div className="section-label"><span>Passos para concluir</span><small>{existing.checklist.filter(i=>i.done).length} de {existing.checklist.length}</small></div><div className="checklist-progress"><i style={{width:`${existing.checklist.length?existing.checklist.filter(i=>i.done).length/existing.checklist.length*100:0}%`}}/></div>{existing.checklist.map(i=><label className={`checklist-item ${i.done?'checklist-done':''}`} key={i.id}><input type="checkbox" checked={i.done} disabled={!editable||busy} onChange={()=>void onPatch(existing,{checklist:existing.checklist.map(x=>x.id===i.id?{...x,done:!x.done}:x)})}/><span>{i.text}</span>{editable&&<button className="icon-btn" type="button" aria-label={`Remover ${i.text}`} disabled={busy} onClick={()=>void onPatch(existing,{checklist:existing.checklist.filter(x=>x.id!==i.id)})}><X size={13}/></button>}</label>)}{!existing.checklist.length&&<Empty icon={ListChecks} title="Pequenos passos, grandes entregas" text="Divida a atividade em itens para acompanhar o progresso."/>}{editable&&<form className="inline-form" onSubmit={async e=>{e.preventDefault();if(checkText.trim()&&await onPatch(existing,{checklist:[...existing.checklist,{id:crypto.randomUUID(),text:checkText.trim(),done:false}]}))setCheckText('');}}><input placeholder="Adicionar um item ao checklist…" value={checkText} maxLength={500} onChange={e=>setCheckText(e.target.value)} required/><Button type="submit" disabled={busy} icon={Plus}>Adicionar</Button></form>}</div>}
 {tab==='comments'&&existing&&<div className="comments-panel">{existing.comments.length?existing.comments.map(c=><div className="comment" key={c.id}><Avatar profile={profiles.find(p=>p.id===c.author_id)} size="small"/><div><div><strong>{c.author}</strong><time>{dateTime(c.created_at)}</time></div><p>{c.text}</p></div></div>):<Empty icon={MessageSquare} title="Contexto também faz parte da entrega" text="Registre atualizações e informações importantes sobre a atividade."/>}{editable&&<form className="comment-form" onSubmit={async e=>{e.preventDefault();if(comment.trim()&&await onPatch(existing,{comments:[...existing.comments,{id:crypto.randomUUID(),text:comment.trim(),author:user.full_name,author_id:user.id,created_at:new Date().toISOString()}]}))setComment('');}}><textarea placeholder="Compartilhe uma atualização…" value={comment} maxLength={5000} onChange={e=>setComment(e.target.value)} required rows={3}/><Button type="submit" disabled={busy} icon={MessageSquare}>Publicar comentário</Button></form>}</div>}
 {tab==='events'&&existing&&<div className="timeline">{events.filter(e=>e.activity_id===existing.id).map(e=><div className="timeline-item" key={e.id}><span><History size={13}/></span><div><strong>{e.action}</strong><p>{e.actor_name} · {dateTime(e.created_at)}</p>{e.details&&<small>{e.details}</small>}</div></div>)}</div>}
 </div><footer className="drawer-footer"><div>{existing&&editable&&<Button kind="secondary" icon={CheckCheck} onClick={()=>onComplete(existing)} disabled={busy}>Concluir</Button>}{existing?.status==='completed'&&(canReopen(user,existing,cards)?<Button kind="secondary" icon={RefreshCw} onClick={()=>onReopen(existing)}>Reabrir como nova</Button>:<span className="readonly-label"><LockKeyhole size={13}/>{cards.some(c=>c.root_id===existing.root_id&&c.status!=='completed')?'Já existe uma continuação ativa':'Registro preservado'}</span>)}</div><div><Button kind="ghost" onClick={onClose}>{editable?'Cancelar':'Fechar'}</Button>{editable&&tab==='details'&&<button className="btn btn-primary" type="submit" form="card-form" disabled={busy}>{busy?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>} {isNew?'Criar atividade':'Salvar alterações'}</button>}</div></footer></section></div>;
}

function ReopenModal({card,user,profiles,busy,onClose,onSubmit}:{card:Card;user:Profile;profiles:Profile[];busy:boolean;onClose:()=>void;onSubmit:(r:string,s:string,d:string,a:string)=>Promise<void>}) {const [reason,setReason]=useState(''),[start,setStart]=useState(today()),[due,setDue]=useState(dateOffset(3)),[owner,setOwner]=useState(card.assignee_id);return <Modal title="Uma nova etapa para esta atividade" subtitle={`Reabertura de ${card.code}`} onClose={onClose}><div className="reopen-explanation"><Link2 size={20}/><p>Um novo ID será criado, com vínculo permanente a <strong>{card.code}</strong>. O card original continuará concluído.</p></div><form onSubmit={e=>{e.preventDefault();void onSubmit(reason,start,due,owner);}}><label>Motivo da reabertura<textarea required maxLength={2000} rows={3} placeholder="Explique o que precisa ser retomado…" value={reason} onChange={e=>setReason(e.target.value)}/></label><div className="form-grid"><label>Novo início<input type="date" value={start} onChange={e=>setStart(e.target.value)} required/></label><label>Novo término previsto<input type="date" value={due} min={start} onChange={e=>setDue(e.target.value)} required/></label></div><label>Responsável<select value={owner} onChange={e=>setOwner(e.target.value)} required disabled={user.role==='technician'}>{profiles.filter(p=>p.active&&!p.must_change_password).map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label><div className="modal-actions"><Button kind="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy} icon={RefreshCw}>Criar continuação</Button></div></form></Modal>;}
function UserModal({demo,smtpReady,profiles,busy,onClose,onSubmit}:{demo:boolean;smtpReady:boolean;profiles:Profile[];busy:boolean;onClose:()=>void;onSubmit:(i:{full_name:string;username:string;email:string;role:Role})=>Promise<void>}) {const [first,setFirst]=useState(''),[last,setLast]=useState(''),[username,setUsername]=useState(''),[email,setEmail]=useState(''),[role,setRole]=useState<Role>('technician'),[error,setError]=useState('');function rename(f:string,l:string){setFirst(f);setLast(l);setUsername(normalizeUsername(f,l));}return <Modal title="Uma nova pessoa na equipe" subtitle="Cadastre o acesso. O TI Flow cuida dos próximos passos." onClose={onClose}>{!demo&&!smtpReady&&<div className="notice"><Mail size={19}/><div><strong>Configure o serviço de e-mail primeiro</strong><p>O cadastro será liberado após a configuração do envio de boas-vindas e senha temporária.</p></div></div>}<form onSubmit={e=>{e.preventDefault();setError('');if(!/^[a-z]+\.[a-z]+$/.test(username))return setError('Use nome.sobrenome, com letras sem acentos e sem espaços.');if(profiles.some(p=>p.username===username))return setError('Login já utilizado. Escolha outro sobrenome ou sobrenome composto.');void onSubmit({full_name:`${first.trim()} ${last.trim()}`,username,email:email.trim(),role});}}><div className="form-grid"><label>Nome<input required value={first} onChange={e=>rename(e.target.value,last)} placeholder="Nome" maxLength={60}/></label><label>Sobrenome<input required value={last} onChange={e=>rename(first,e.target.value)} placeholder="Sobrenome" maxLength={100}/></label></div><label>Login<input required value={username} onChange={e=>setUsername(e.target.value.toLowerCase())} placeholder="nome.sobrenome" maxLength={100}/></label><label>E-mail<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="pessoa@empresa.com.br" maxLength={254}/></label><label>Perfil<select value={role} onChange={e=>setRole(e.target.value as Role)}><option value="technician">Técnico</option><option value="manager">Gestor</option><option value="admin">Administrador</option></select></label><div className="email-sequence"><div><span>1</span><div><strong>Boas-vindas</strong><small>Apresentação e instruções de acesso</small></div><small>Imediato</small></div><i/><div><span>2</span><div><strong>Senha temporária</strong><small>12 caracteres · troca obrigatória no primeiro acesso</small></div><small>+ 2 min</small></div></div>{demo&&<p className="demo-form-note">Modo demonstração: nenhum e-mail real será enviado.</p>}{error&&<p className="form-error">{error}</p>}<div className="modal-actions"><Button kind="secondary" onClick={onClose}>Cancelar</Button><Button type="submit" disabled={busy||!demo&&!smtpReady} icon={Plus}>Criar usuário</Button></div></form></Modal>;}
function EmailPreview({onClose}:{onClose:()=>void}) {const [tab,setTab]=useState('welcome');return <Modal title="Um começo bem organizado" subtitle="Prévia ilustrativa dos dois e-mails de acesso." onClose={onClose} wide><div className="email-preview-tabs"><button className={tab==='welcome'?'selected':''} onClick={()=>setTab('welcome')}>1. Boas-vindas</button><button className={tab==='password'?'selected':''} onClick={()=>setTab('password')}>2. Senha · + 2 min</button></div><div className="email-preview"><Brand/><span className="email-eyebrow">AUTOMAÇÕES TI</span><h2>{tab==='welcome'?'Boas-vindas ao seu novo fluxo.':'Seu acesso está pronto.'}</h2><p>Olá, integrante da equipe!</p>{tab==='welcome'?<><p>Seu acesso ao TI Flow foi criado. Agora você tem um espaço para organizar atividades, acompanhar prioridades e trabalhar junto com a equipe.</p><div className="email-callout"><strong>Seu login: nome.sobrenome</strong><p>Em aproximadamente 2 minutos, você receberá outro e-mail com sua senha temporária. No primeiro acesso, será necessário escolher uma nova senha.</p></div></>:<><p>Use o login e a senha temporária abaixo para entrar.</p><div className="email-callout"><span>LOGIN</span><strong>nome.sobrenome</strong><span>SENHA TEMPORÁRIA · EXEMPLO ILUSTRATIVO</span><strong className="email-password">Ab7Kp2Mx9Qr4</strong></div><p>A senha temporária é válida por 24 horas após o envio. Você deverá substituí-la no primeiro acesso por uma senha de 8 a 12 caracteres, com letras e números.</p></>}<span className="email-button">Acessar o TI Flow <ArrowRight size={15}/></span><footer>Este é um exemplo. Nenhum e-mail foi enviado.</footer></div></Modal>;}
